import{_ as a,C as i,o as s,c as l,j as o,a as r,E as n,a2 as d}from"./chunks/framework.CBxkvBm_.js";const b=JSON.parse('{"title":"Simulation Solvers & Numerical Integrators","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/simulation-solvers.md","filePath":"architecture/simulation-solvers.md"}'),u={name:"architecture/simulation-solvers.md"};function c(m,e,p,g,h,S){const t=i("MermaidBlock");return s(),l("div",null,[e[0]||(e[0]=o("h1",{id:"simulation-solvers-numerical-integrators",tabindex:"-1"},[r("Simulation Solvers & Numerical Integrators "),o("a",{class:"header-anchor",href:"#simulation-solvers-numerical-integrators","aria-label":'Permalink to "Simulation Solvers & Numerical Integrators"'},"​")],-1)),e[1]||(e[1]=o("p",null,[r("ModelScript embeds a multi-tier suite of numerical solvers in "),o("code",null,"@modelscript/simulate"),r(" to support both desktop simulations and massive batched cloud/WebGPU parameter sweeps.")],-1)),e[2]||(e[2]=o("hr",null,null,-1)),e[3]||(e[3]=o("h2",{id:"supported-solvers",tabindex:"-1"},[r("Supported Solvers "),o("a",{class:"header-anchor",href:"#supported-solvers","aria-label":'Permalink to "Supported Solvers"'},"​")],-1)),n(t,{code:"flowchart%20TD%0A%20%20%20%20DAE%5B%22Flat%20DAE%20Representation%22%5D%20--%3E%20ROUTE%7B%22Problem%20Type%22%7D%0A%0A%20%20%20%20ROUTE%20--%3E%7CStiff%20%2F%20Non-Stiff%20ODE%7C%20SUNDIALS_CVODE%5B%22SUNDIALS%20CVODE%20(BDF%20%26%20Adams-Moulton)%22%5D%0A%20%20%20%20ROUTE%20--%3E%7CIndex-1%20DAE%7C%20SUNDIALS_IDA%5B%22SUNDIALS%20IDA%20(Variable-order%20BDF)%22%5D%0A%20%20%20%20ROUTE%20--%3E%7CBrowser%20%2F%20Lightweight%7C%20WASM_SOLVER%5B%22WASM%20Integrators%20(DOPRI5%20%26%20RK4)%22%5D%0A%20%20%20%20ROUTE%20--%3E%7CBatched%20%2F%20Monte%20Carlo%7C%20WEBGPU%5B%22WebGPU%20Batched%20SIMD%20Solver%22%5D%0A%20%20%20%20ROUTE%20--%3E%7COptimal%20Control%7C%20COLLOCATION%5B%22Direct%20Collocation%20(Interior%20Point)%22%5D%0A%20%20%20%20ROUTE%20--%3E%7CReal-Time%20ROM%7C%20SURROGATE%5B%22Surrogate%20Models%20(Neural%20ODE%20%2F%20GP)%22%5D%0A"}),e[4]||(e[4]=d('<hr><h2 id="_1-sundials-cvode-ida-integrators" tabindex="-1">1. SUNDIALS CVODE &amp; IDA Integrators <a class="header-anchor" href="#_1-sundials-cvode-ida-integrators" aria-label="Permalink to &quot;1. SUNDIALS CVODE &amp; IDA Integrators&quot;">​</a></h2><p>For high-precision industrial models, ModelScript integrates Lawrence Livermore National Laboratory&#39;s <strong>SUNDIALS</strong> suite compiled to WebAssembly:</p><ul><li><strong>CVODE</strong>: Solves Initial Value Problems (IVPs) for stiff and non-stiff systems of ordinary differential equations (ODEs). Uses Variable-Order Variable-Step-size Adams-Moulton methods for non-stiff systems and Backward Differentiation Formulas (BDF) for stiff systems.</li><li><strong>IDA</strong>: Solves Initial Value Problems for systems of differential-algebraic equations (DAEs) of index up to 1: $$F(t, y, y&#39;) = 0$$ Includes dense and sparse linear solvers with adaptive step-size control.</li></ul><hr><h2 id="_2-webgpu-batched-parallel-solvers" tabindex="-1">2. WebGPU Batched Parallel Solvers <a class="header-anchor" href="#_2-webgpu-batched-parallel-solvers" aria-label="Permalink to &quot;2. WebGPU Batched Parallel Solvers&quot;">​</a></h2><p>When performing Monte Carlo uncertainty analysis or hyperparameter sweeps, sequential simulation is a bottleneck.</p><p>ModelScript compiles linearized DAE blocks into WebGPU compute shaders (<code>@modelscript/simulate/gpu</code>):</p><ul><li>Runs thousands of parameter combinations in parallel on GPU hardware.</li><li>Scales efficiently across client GPUs in browsers and headless datacenter instances.</li><li>Returns statistical distributions, mean trajectories, and variance envelopes directly.</li></ul><hr><h2 id="_3-direct-collocation-optimal-control" tabindex="-1">3. Direct Collocation Optimal Control <a class="header-anchor" href="#_3-direct-collocation-optimal-control" aria-label="Permalink to &quot;3. Direct Collocation Optimal Control&quot;">​</a></h2><p>ModelScript formulates dynamic optimization and optimal control problems directly from Modelica models:</p><p>$$\\min_{u(t)} \\int_0^T L(x(t), u(t), t) , dt$$ $$\\text{subject to } F(t, x, \\dot{x}, u) = 0, \\quad u_{\\min} \\le u(t) \\le u_{\\max}$$</p><ul><li><strong>Transcription</strong>: Transcribes the continuous system into non-linear programming (NLP) problems using Radau or Lobatto collocation points.</li><li><strong>Solvers</strong>: Solves the resulting sparse NLP using interior-point optimization techniques.</li></ul><hr><h2 id="_4-surrogate-reduced-order-models-rom" tabindex="-1">4. Surrogate Reduced Order Models (ROM) <a class="header-anchor" href="#_4-surrogate-reduced-order-models-rom" aria-label="Permalink to &quot;4. Surrogate Reduced Order Models (ROM)&quot;">​</a></h2><p>High-fidelity 3D simulations (such as CFD or FEA) are often too computationally expensive for real-time control loops or web deployment.</p><p>ModelScript&#39;s surrogate modeling pipeline (<code>msx surrogate</code>):</p><ol><li><strong>Sampling</strong>: Generates experimental design samples (Latin Hypercube, Sobol sequences).</li><li><strong>Execution</strong>: Evaluates high-fidelity runs across parameter spaces.</li><li><strong>Training</strong>: Trains compact surrogate models using: <ul><li>Polynomial Chaos Expansion (PCE)</li><li>Gaussian Process Regression (Kriging)</li><li>Neural Ordinary Differential Equations (Neural ODEs)</li></ul></li><li><strong>Embedding</strong>: Exports the trained surrogate as a standardized FMI Functional Mock-up Unit (FMU) or standalone WebAssembly module.</li></ol>',19))])}const D=a(u,[["render",c]]);export{b as __pageData,D as default};
